30	CREATE TABLE IF NOT EXISTS head_ledger (
31	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
32	    batch_id BIGINT NOT NULL,
33	    head_no VARCHAR(64) NOT NULL,
34	    status VARCHAR(32) NOT NULL,
35	    inspection_result VARCHAR(32) NULL,
36	    judgment_category VARCHAR(32) NULL,
37	    high_temp BOOLEAN NULL,
38	    circulation_area VARCHAR(128) NULL,
39	    inventory_marked BOOLEAN NOT NULL DEFAULT FALSE,
40	    updated_at VARCHAR(40) NOT NULL,
41	    CONSTRAINT uk_head_batch_no UNIQUE (batch_id, head_no)
42	);
43	COMMENT ON TABLE head_ledger IS '头只台账：每头只一行，记录同步检验、判定与库存标识，可复算';
44	COMMENT ON COLUMN head_ledger.batch_id IS '所属屠宰批次主键';
45	COMMENT ON COLUMN head_ledger.head_no IS '头只编号，批次内唯一';
46	COMMENT ON COLUMN head_ledger.status IS '头只状态：PENDING 待检 / INSPECTED 已同步检验';
47	COMMENT ON COLUMN head_ledger.inspection_result IS '同步检验结果（如 NORMAL/ABNORMAL），NULL 表示未检';
48	COMMENT ON COLUMN head_ledger.judgment_category IS '判定类别：QUALIFIED 合格 / CONDITIONAL 有条件食用 / RENDERING 化制 / DESTRUCTION 销毁，NULL 表示未判定';
49	COMMENT ON COLUMN head_ledger.high_temp IS '有条件食用是否标注高温处理，NULL 表示不适用';
50	COMMENT ON COLUMN head_ledger.circulation_area IS '有条件食用限定流通区域，NULL 表示不限定或不适用';
51	COMMENT ON COLUMN head_ledger.inventory_marked IS '库存标识：判定合格的头只在判定事务内同步置 TRUE';
52	COMMENT ON COLUMN head_ledger.updated_at IS '行最近更新时间（UTC ISO-8601）';
53	
54	CREATE TABLE IF NOT EXISTS judgment_detail (
55	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
56	    batch_id BIGINT NOT NULL,
57	    head_no VARCHAR(64) NOT NULL,
58	    category VARCHAR(32) NOT NULL,
59	    high_temp BOOLEAN NOT NULL DEFAULT FALSE,
60	    circulation_area VARCHAR(128) NULL,
61	    created_at VARCHAR(40) NOT NULL,
62	    CONSTRAINT uk_judgment_head UNIQUE (batch_id, head_no)
63	);
64	COMMENT ON TABLE judgment_detail IS '判定明细：每头只一条判定记录，与台账共同支撑复算';
65	COMMENT ON COLUMN judgment_detail.batch_id IS '所属屠宰批次主键';
66	COMMENT ON COLUMN judgment_detail.head_no IS '头只编号';
67	COMMENT ON COLUMN judgment_detail.category IS '判定类别：QUALIFIED/CONDITIONAL/RENDERING/DESTRUCTION';
68	COMMENT ON COLUMN judgment_detail.high_temp IS '有条件食用是否标注高温处理';
69	COMMENT ON COLUMN judgment_detail.circulation_area IS '有条件食用限定流通区域，NULL 表示不适用';
70	COMMENT ON COLUMN judgment_detail.created_at IS '判定登记时间（UTC ISO-8601）';
71	
72	CREATE TABLE IF NOT EXISTS harmless_receipt (
73	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
74	    batch_id BIGINT NOT NULL,
75	    receipt_no VARCHAR(64) NOT NULL,
76	    category VARCHAR(32) NOT NULL,
77	    head_count INT NOT NULL,
78	    processor VARCHAR(128) NOT NULL,
79	    late BOOLEAN NOT NULL DEFAULT FALSE,
80	    received_at VARCHAR(40) NOT NULL,
81	    CONSTRAINT uk_receipt_no UNIQUE (batch_id, receipt_no)
82	);
83	COMMENT ON TABLE harmless_receipt IS '无害化处理回执：化制/销毁判定头只的处理闭环凭证，与判定数勾稽';
84	COMMENT ON COLUMN harmless_receipt.batch_id IS '所属屠宰批次主键';
85	COMMENT ON COLUMN harmless_receipt.receipt_no IS '回执编号，批次内唯一';
86	COMMENT ON COLUMN harmless_receipt.category IS '回执对应判定类别：RENDERING 化制 / DESTRUCTION 销毁';
87	COMMENT ON COLUMN harmless_receipt.head_count IS '回执载明处理头只数，出厂核销时须与同类判定数恰等';
88	COMMENT ON COLUMN harmless_receipt.processor IS '无害化处理单位（合成数据）';
89	COMMENT ON COLUMN harmless_receipt.late IS '是否核销后迟到的回执，TRUE 仅记录不参与勾稽';
90	COMMENT ON COLUMN harmless_receipt.received_at IS '回执登记时间（UTC ISO-8601）';
91	
92	CREATE TABLE IF NOT EXISTS late_event (
93	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
94	    batch_id BIGINT NOT NULL,
95	    event_type VARCHAR(64) NOT NULL,
96	    detail VARCHAR(512) NOT NULL,
97	    created_at VARCHAR(40) NOT NULL
98	);
99	COMMENT ON TABLE late_event IS '迟到事件台账：批次核销终态后到达的回执等事件，仅记录并告警，不改变批次状态';
100	COMMENT ON COLUMN late_event.batch_id IS '所属屠宰批次主键';
101	COMMENT ON COLUMN late_event.event_type IS '事件类型，如 LATE_RECEIPT 迟到回执';
102	COMMENT ON COLUMN late_event.detail IS '事件明细（合成数据）';
103	COMMENT ON COLUMN late_event.created_at IS '事件记录时间（UTC ISO-8601）';
104	
105	CREATE TABLE IF NOT EXISTS idempotency_record (
106	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
107	    request_id VARCHAR(128) NOT NULL,
108	    endpoint VARCHAR(128) NOT NULL,
109	    fingerprint VARCHAR(128) NOT NULL,
110	    response_body CLOB NOT NULL,
111	    created_at VARCHAR(40) NOT NULL,
112	    CONSTRAINT uk_request_id UNIQUE (request_id)
113	);
114	COMMENT ON TABLE idempotency_record IS '幂等登记：requestId 全局唯一，指纹覆盖 requestId 与全部业务字段，同键同参返回首次结果';
115	COMMENT ON COLUMN idempotency_record.request_id IS '调用方请求标识，全局唯一';
116	COMMENT ON COLUMN idempotency_record.endpoint IS '受理接口标识';
117	COMMENT ON COLUMN idempotency_record.fingerprint IS '请求指纹：requestId 与全部业务字段的 SHA-256';
118	COMMENT ON COLUMN idempotency_record.response_body IS '首次受理的响应报文（JSON），同键同参重放时原样返回';
119	COMMENT ON COLUMN idempotency_record.created_at IS '登记时间（UTC ISO-8601）';
120	
121	-- ========== 风险抽检层（合成规则，不用于生产） ==========
122	
123	CREATE TABLE IF NOT EXISTS risk_binding (
124	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
125	    batch_id BIGINT NOT NULL,
126	    version INT NOT NULL,
127	    level VARCHAR(32) NOT NULL,
128	    rule_version VARCHAR(64) NOT NULL,
129	    current_sequence_no BIGINT NOT NULL,
130	    created_at VARCHAR(40) NOT NULL,
131	    updated_at VARCHAR(40) NOT NULL,
132	    CONSTRAINT uk_risk_binding_batch UNIQUE (batch_id)
133	);
134	COMMENT ON TABLE risk_binding IS '风险绑定：受控批次宰前检疫合格后绑定合成风险等级，每批仅一行，承载乐观版本与当前清单序号';
135	COMMENT ON COLUMN risk_binding.batch_id IS '所属屠宰批次主键';
136	COMMENT ON COLUMN risk_binding.version IS '风险版本：首次绑定为 1，每次成功变更（等级变更/接受新结果）加 1，同结果重复不增加，迟到事件不增加';
137	COMMENT ON COLUMN risk_binding.level IS '当前风险等级：NORMAL 普通抽检10% / TIGHTENED 加严抽检30%';
138	COMMENT ON COLUMN risk_binding.rule_version IS '当前合成风险规则版本（随每次清单冻结更新，仅合成数据）';
139	COMMENT ON COLUMN risk_binding.current_sequence_no IS '当前清单序号：同一批次只一个当前清单，原子扩充沿用原序号，补充清单序号加 1';
140	COMMENT ON COLUMN risk_binding.created_at IS '绑定时间（UTC ISO-8601）';
141	COMMENT ON COLUMN risk_binding.updated_at IS '最近一次成功风险变更时间（UTC ISO-8601）';
142	
143	CREATE TABLE IF NOT EXISTS risk_checklist (
144	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
145	    batch_id BIGINT NOT NULL,
146	    sequence_no BIGINT NOT NULL,
147	    kind VARCHAR(32) NOT NULL,
148	    level VARCHAR(32) NOT NULL,
149	    rule_version VARCHAR(64) NOT NULL,
150	    status VARCHAR(32) NOT NULL,
151	    frozen_declared CLOB NOT NULL,
152	    frozen_samples CLOB NOT NULL,
153	    created_at VARCHAR(40) NOT NULL,
154	    completed_at VARCHAR(40) NULL,
155	    CONSTRAINT uk_risk_checklist_seq UNIQUE (batch_id, sequence_no)
156	);
157	COMMENT ON TABLE risk_checklist IS '风险抽检清单：冻结编号清单、风险规则版本及申报头只集合，同一批次只一个当前清单';
158	COMMENT ON COLUMN risk_checklist.batch_id IS '所属屠宰批次主键';
159	COMMENT ON COLUMN risk_checklist.sequence_no IS '清单序号，批次内从 1 递增：原子扩充沿用原序号，补充清单另开新序号';
160	COMMENT ON COLUMN risk_checklist.kind IS '清单类型：INITIAL 首份 / EXPANDED 提高等级原子扩充 / SUPPLEMENTARY 已完成后新增风险补充清单';
161	COMMENT ON COLUMN risk_checklist.level IS '清单冻结时的风险等级：NORMAL/TIGHTENED';
162	COMMENT ON COLUMN risk_checklist.rule_version IS '清单冻结时的合成风险规则版本';
163	COMMENT ON COLUMN risk_checklist.status IS '清单状态：OPEN 进行中（可提交结果）/ COMPLETED 已完成（全部冻结样本有结果，不可改）';
164	COMMENT ON COLUMN risk_checklist.frozen_declared IS '冻结申报头只集合（JSON 数组，字典序），与头只台账集合一致';
165	COMMENT ON COLUMN risk_checklist.frozen_samples IS '冻结抽检编号集合（JSON 数组，字典序）：申报集合字典序前 ceil(总数×比例) 只且至少 1 只';
166	COMMENT ON COLUMN risk_checklist.created_at IS '清单冻结时间（UTC ISO-8601）';
167	COMMENT ON COLUMN risk_checklist.completed_at IS '清单完成时间（UTC ISO-8601，最后一只结果登记时刻），NULL 表示未完成';
168	
169	CREATE TABLE IF NOT EXISTS risk_sample (
170	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
171	    batch_id BIGINT NOT NULL,
172	    sequence_no BIGINT NOT NULL,
173	    head_no VARCHAR(64) NOT NULL,
174	    result VARCHAR(16) NOT NULL,
175	    submitted_at VARCHAR(40) NOT NULL,
176	    CONSTRAINT uk_risk_sample UNIQUE (batch_id, sequence_no, head_no)
177	);
178	COMMENT ON TABLE risk_sample IS '抽检逐只结果：每个冻结样本至多一条结果，同结果重复不新增，异结果冲突，清单外编号拒绝';
179	COMMENT ON COLUMN risk_sample.batch_id IS '所属屠宰批次主键';
180	COMMENT ON COLUMN risk_sample.sequence_no IS '所属抽检清单序号';
181	COMMENT ON COLUMN risk_sample.head_no IS '头只编号，须属于同序号清单冻结抽检集合';
182	COMMENT ON COLUMN risk_sample.result IS '抽检结果：NEGATIVE 阴性 / POSITIVE 阳性（任一阳性整批专项隔离）';
183	COMMENT ON COLUMN risk_sample.submitted_at IS '结果提交业务精确时刻（UTC ISO-8601）';
184	
185	CREATE TABLE IF NOT EXISTS risk_change_event (
186	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
187	    batch_id BIGINT NOT NULL,
188	    event_type VARCHAR(32) NOT NULL,
189	    from_level VARCHAR(32) NULL,
190	    to_level VARCHAR(32) NOT NULL,
191	    from_rule_version VARCHAR(64) NULL,
192	    to_rule_version VARCHAR(64) NOT NULL,
193	    sequence_no BIGINT NOT NULL,
194	    from_version INT NOT NULL,
195	    to_version INT NOT NULL,
196	    created_at VARCHAR(40) NOT NULL
197	);
198	COMMENT ON TABLE risk_change_event IS '风险变更证据台账：绑定、提高等级原子扩充、补充清单逐次留痕，支撑复算与审计';
199	COMMENT ON COLUMN risk_change_event.batch_id IS '所属屠宰批次主键';
200	COMMENT ON COLUMN risk_change_event.event_type IS '事件类型：BIND 首次绑定 / EXPAND 原子扩充 / SUPPLEMENT 补充清单';
201	COMMENT ON COLUMN risk_change_event.from_level IS '变更前风险等级，BIND 时为 NULL';
202	COMMENT ON COLUMN risk_change_event.to_level IS '变更后风险等级';
203	COMMENT ON COLUMN risk_change_event.from_rule_version IS '变更前规则版本，BIND 时为 NULL';
204	COMMENT ON COLUMN risk_change_event.to_rule_version IS '变更后规则版本';
205	COMMENT ON COLUMN risk_change_event.sequence_no IS '事件关联清单序号（扩充沿用原序号，补充清单为新序号）';
206	COMMENT ON COLUMN risk_change_event.from_version IS '变更前风险版本，BIND 时为 0';
207	COMMENT ON COLUMN risk_change_event.to_version IS '变更后风险版本';
208	COMMENT ON COLUMN risk_change_event.created_at IS '事件记录时间（UTC ISO-8601）';
209

