15	import java.util.Set;
16	import java.util.function.Supplier;
17	
18	import com.example.starter.domain.BatchStatus;
19	import com.example.starter.domain.JudgmentCategory;
20	import com.example.starter.error.ApiException;
21	import com.example.starter.repo.BatchRepository;
22	import com.example.starter.repo.BatchRepository.BatchRow;
23	import com.example.starter.repo.BatchRepository.HeadRow;
24	import com.example.starter.repo.BatchRepository.IdempotencyRow;
25	import com.example.starter.repo.BatchRepository.JudgmentRow;
