27	import com.example.starter.web.dto.BatchView;
28	import com.example.starter.web.dto.DeclareRequest;
29	import com.example.starter.web.dto.DeclareResponse;
30	import com.example.starter.web.dto.InspectionRequest;
31	import com.example.starter.web.dto.InspectionResponse;
32	import com.example.starter.web.dto.JudgmentRequest;
33	import com.example.starter.web.dto.JudgmentResponse;
34	import com.example.starter.web.dto.PreQuarantineRequest;
35	import com.example.starter.web.dto.PreQuarantineResponse;
