37	import com.example.starter.web.dto.ReceiptResponse;
38	import com.example.starter.web.dto.ReconciliationEntry;
39	import com.example.starter.web.dto.ReleaseRequest;
40	import com.example.starter.web.dto.ReleaseResponse;
41	import com.fasterxml.jackson.databind.ObjectMapper;
42	import org.slf4j.Logger;
43	import org.slf4j.LoggerFactory;
44	import org.springframework.dao.DuplicateKeyException;
45	import org.springframework.stereotype.Service;
46	import org.springframework.transaction.PlatformTransactionManager;
47	import org.springframework.transaction.TransactionDefinition;
48	import org.springframework.transaction.annotation.Transactional;
49	import org.springframework.transaction.support.TransactionTemplate;
50	
51	/**
52	 * 屠宰检疫业务服务：申报→宰前检疫→同步检验→判定分流→出厂核销。
53	 * 申报、检验与回执登记均以 requestId 幂等；判定分流与库存标识在同一事务内完成。
54	 */
55	@Service
56	public class BatchService {
57	
58	    private static final Logger log = LoggerFactory.getLogger(BatchService.class);
59	
60	    /** 宰前检疫有效期：自申报起 6 小时（UTC），恰满 6 小时即失效须重新申报。 */
61	    static final Duration QUARANTINE_VALIDITY = Duration.ofHours(6);
62	
63	    private final BatchRepository repo;
64	    private final Clock clock;
65	    private final ObjectMapper objectMapper;
66	    /** 风险抽检门禁：受控批次全部样本阴性且抽检完成才允许出厂核销。 */
67	    private final RiskService riskService;
68	    /** 漏检暂停独立事务：判定请求整体回滚时，暂停状态仍须落库。 */
69	    private final TransactionTemplate pauseTemplate;
70	
71	    public BatchService(BatchRepository repo, Clock clock, ObjectMapper objectMapper,
72	                        PlatformTransactionManager transactionManager, RiskService riskService) {
73	        this.repo = repo;
74	        this.clock = clock;
75	        this.objectMapper = objectMapper;
76	        this.riskService = riskService;
77	        this.pauseTemplate = new TransactionTemplate(transactionManager);
78	        this.pauseTemplate.setPropagationBehavior(TransactionDefinition.PROPAGATION_REQUIRES_NEW);
79	    }
80	
81	    // ---------- 宰前申报 ----------
82	
83	    /**
84	     * 宰前申报：新批次建档并建立头只台账；批次已存在且 6 小时有效期恰满/已过且未进入后续环节时，
85	     * 视为重新申报，重置申报时间与头只台账；其余情况拒绝。
86	     */
87	    @Transactional
88	    public DeclareResponse declare(DeclareRequest req) {
89	        return idempotent("declare", req.requestId(), req, DeclareResponse.class, () -> doDeclare(req));
90	    }
91	
92	    private DeclareResponse doDeclare(DeclareRequest req) {
93	        validateDistinctHeadNos(req.headNos());
94	        String now = now();
95	        Optional<BatchRow> existing = repo.findBatchByNo(req.batchNo());
96	        if (existing.isEmpty()) {
97	            repo.insertBatch(req.batchNo(), req.species(), req.farmOrigin(), req.headNos().size(),
98	                    BatchStatus.DECLARED.name(), now, now);
99	            BatchRow batch = mustFind(req.batchNo());
100	            insertHeads(batch.id(), req.headNos(), now);
101	            return new DeclareResponse(batch.batchNo(), batch.status(), now, req.headNos().size());
102	        }
103	        BatchRow batch = existing.get();
104	        if (!BatchStatus.DECLARED.name().equals(batch.status())) {
105	            throw ApiException.conflict("批次已进入后续环节，不允许重新申报");
106	        }
107	        Instant declaredAt = Instant.parse(batch.declaredAt());
108	        if (Instant.now(clock).isBefore(declaredAt.plus(QUARANTINE_VALIDITY))) {
109	            throw ApiException.conflict("批次已申报且仍在宰前检疫 6 小时有效期内");
110	        }
111	        repo.resetForRedeclare(batch.id(), req.species(), req.farmOrigin(), req.headNos().size(), now);
112	        repo.deleteHeads(batch.id());
113	        insertHeads(batch.id(), req.headNos(), now);
114	        return new DeclareResponse(batch.batchNo(), BatchStatus.DECLARED.name(), now, req.headNos().size());
115	    }
116	
117	    // ---------- 宰前检疫 ----------
118	
119	    /**
120	     * 宰前检疫：自申报起 6 小时内（UTC）有效，恰满 6 小时未屠宰须重新申报。
121	     * 同一批次同时刻只允许一条检验链（DECLARED→PRE_QUARANTINED 条件流转保证）。
122	     */
123	    @Transactional
124	    public PreQuarantineResponse preQuarantine(String batchNo, PreQuarantineRequest req) {
125	        return idempotent("pre-quarantine", req.requestId(), req, PreQuarantineResponse.class,
126	                () -> doPreQuarantine(batchNo));
127	    }
128	
129	    private PreQuarantineResponse doPreQuarantine(String batchNo) {
130	        BatchRow batch = mustFind(batchNo);
131	        if (!BatchStatus.DECLARED.name().equals(batch.status())) {
132	            throw ApiException.conflict("批次当前状态不允许宰前检疫");
133	        }
134	        Instant nowInstant = Instant.now(clock);
135	        Instant deadline = Instant.parse(batch.declaredAt()).plus(QUARANTINE_VALIDITY);
136	        if (!nowInstant.isBefore(deadline)) {
137	            throw ApiException.unprocessable("宰前检疫已超过申报后 6 小时有效期，须重新申报");
138	        }
139	        String now = nowInstant.toString();
140	        int updated = repo.markPreQuarantined(batch.id(), now);
141	        if (updated == 0) {
142	            throw ApiException.conflict("并发检疫冲突：同一批次同时刻只允许一条检验链");
143	        }
144	        return new PreQuarantineResponse(batchNo, BatchStatus.PRE_QUARANTINED.name(), now);
145	    }
146	
147	    // ---------- 同步检验 ----------
148	
149	    /**
150	     * 同步检验：按头只编号一一对应登记；漏检头只将在判定分流时导致整批暂停流转。
151	     */
152	    @Transactional
153	    public InspectionResponse inspect(String batchNo, InspectionRequest req) {
154	        return idempotent("inspection", req.requestId(), req, InspectionResponse.class,
155	                () -> doInspect(batchNo, req));
156	    }
157	
158	    private InspectionResponse doInspect(String batchNo, InspectionRequest req) {
159	        BatchRow batch = mustFind(batchNo);
160	        String status = batch.status();
161	        boolean inspectable = BatchStatus.PRE_QUARANTINED.name().equals(status)
162	                || BatchStatus.INSPECTING.name().equals(status)
163	                || BatchStatus.PAUSED.name().equals(status)
164	                || BatchStatus.SPECIAL_QUARANTINE.name().equals(status);
165	        if (!inspectable) {
166	            throw ApiException.conflict("批次当前状态不允许同步检验");
167	        }
168	        repo.findHead(batch.id(), req.headNo())
169	                .orElseThrow(() -> ApiException.notFound("头只编号不存在：" + req.headNo()));
170	        int updated = repo.markHeadInspected(batch.id(), req.headNo(), req.result(), now());
171	        if (updated == 0) {
172	            throw ApiException.conflict("头只已完成同步检验，重复检验须使用原 requestId 重放");
173	        }
174	        if (BatchStatus.PRE_QUARANTINED.name().equals(status)) {
175	            repo.transitionStatus(batch.id(), List.of(BatchStatus.PRE_QUARANTINED.name()),
176	                    BatchStatus.INSPECTING.name());
177	        }
178	        int inspected = repo.countInspectedHeads(batch.id());
179	        return new InspectionResponse(batchNo, req.headNo(), "INSPECTED", inspected, batch.headCount());
180	    }
181	
182	    // ---------- 判定分流 ----------
183	
184	    /**
185	     * 判定分流：合格/有条件食用/化制/销毁四类；判定与库存标识在同一事务内完成。
186	     * 存在漏检头只时整批暂停流转并拒绝判定。
187	     */
188	    @Transactional
189	    public JudgmentResponse judge(String batchNo, JudgmentRequest req) {
190	        return idempotent("judgment", req.requestId(), req, JudgmentResponse.class,
191	                () -> doJudge(batchNo, req));
192	    }
193	
194	    private JudgmentResponse doJudge(String batchNo, JudgmentRequest req) {
195	        BatchRow batch = mustFind(batchNo);
196	        String status = batch.status();
197	        boolean judgeable = BatchStatus.PRE_QUARANTINED.name().equals(status)
198	                || BatchStatus.INSPECTING.name().equals(status)
199	                || BatchStatus.PAUSED.name().equals(status)
200	                || BatchStatus.SPECIAL_QUARANTINE.name().equals(status);
201	        if (!judgeable) {
202	            throw ApiException.conflict("批次当前状态不允许判定分流");
203	        }
204	        List<HeadRow> heads = repo.findHeads(batch.id());
205	        List<String> missing = heads.stream()
206	                .filter(h -> "PENDING".equals(h.status()))
207	                .map(HeadRow::headNo)
208	                .toList();
209	        if (!missing.isEmpty()) {
210	            if (!BatchStatus.SPECIAL_QUARANTINE.name().equals(status)) {
211	                // 独立事务落库暂停状态：判定请求本身回滚，整批暂停仍然生效；
212	                // 已专项隔离的批次阳性证据优先，不被 PAUSED 覆盖。
213	                pauseTemplate.executeWithoutResult(s -> repo.transitionStatus(batch.id(),
214	                        List.of(BatchStatus.PRE_QUARANTINED.name(), BatchStatus.INSPECTING.name(),
215	                                BatchStatus.PAUSED.name()),
216	                        BatchStatus.PAUSED.name()));
217	            }
218	            throw ApiException.conflict("存在漏检头只 " + missing + "，整批暂停流转");
219	        }
220	        Map<String, HeadRow> byHeadNo = new LinkedHashMap<>();
221	        for (HeadRow head : heads) {
222	            byHeadNo.put(head.headNo(), head);
223	        }
224	        Set<String> covered = new HashSet<>();
225	        List<ResolvedJudgment> resolved = new ArrayList<>();
226	        for (JudgmentRequest.JudgmentItem item : req.judgments()) {
227	            if (!byHeadNo.containsKey(item.headNo())) {
228	                throw ApiException.unprocessable("判定包含批次外头只：" + item.headNo());
229	            }
230	            if (!covered.add(item.headNo())) {
231	                throw ApiException.unprocessable("判定包含重复头只：" + item.headNo());
232	            }
233	            resolved.add(resolve(item));
234	        }
235	        if (covered.size() != heads.size()) {
236	            throw ApiException.unprocessable("判定须覆盖批次全部头只，缺 "
237	                    + (heads.size() - covered.size()) + " 头");
238	        }
239	        String now = now();
240	        Map<String, Integer> counts = new LinkedHashMap<>();
241	        for (ResolvedJudgment r : resolved) {
242	            boolean qualified = r.category() == JudgmentCategory.QUALIFIED;
243	            boolean conditional = r.category() == JudgmentCategory.CONDITIONAL;
244	            repo.insertJudgment(batch.id(), r.headNo(), r.category().name(),
245	                    conditional && Boolean.TRUE.equals(r.highTemp()),
246	                    conditional ? r.circulationArea() : null, now);
247	            repo.applyJudgment(batch.id(), r.headNo(), r.category().name(),
248	                    conditional ? r.highTemp() : null,
249	                    conditional ? r.circulationArea() : null,
250	                    qualified, now);
251	            counts.merge(r.category().name(), 1, Integer::sum);
252	        }
253	        repo.markJudged(batch.id(), now);
254	        String resultingStatus = repo.findBatchByNo(batchNo)
255	                .map(BatchRow::status).orElse(BatchStatus.JUDGED.name());
256	        return new JudgmentResponse(batchNo, resultingStatus, resolved.size(), counts);
257	    }
258	
259	    /** 单头只判定项解析结果。 */
260	    private record ResolvedJudgment(String headNo, JudgmentCategory category, Boolean highTemp,
261	                                    String circulationArea) {
262	    }
263	
264	    private ResolvedJudgment resolve(JudgmentRequest.JudgmentItem item) {
265	        JudgmentCategory category = parseCategory(item.category());
266	        if (category == JudgmentCategory.CONDITIONAL
267	                && (!Boolean.TRUE.equals(item.highTemp())
268	                || item.circulationArea() == null || item.circulationArea().isBlank())) {
269	            throw ApiException.unprocessable("有条件食用须标注高温处理并限定流通区域");
270	        }
271	        return new ResolvedJudgment(item.headNo(), category, item.highTemp(), item.circulationArea());
272	    }
273	
274	    // ---------- 无害化处理回执 ----------
275	
276	    /**
277	     * 回执登记：化制/销毁须取得无害化处理回执闭环；批次已核销时回执按迟到处理，
278	     * 只记迟到事件并告警，不改变批次状态。
279	     */
280	    @Transactional
281	    public ReceiptResponse registerReceipt(String batchNo, ReceiptRequest req) {
282	        return idempotent("receipt", req.requestId(), req, ReceiptResponse.class,
283	                () -> doRegisterReceipt(batchNo, req));
284	    }
285	
286	    private ReceiptResponse doRegisterReceipt(String batchNo, ReceiptRequest req) {
287	        BatchRow batch = mustFind(batchNo);
288	        JudgmentCategory category = parseCategory(req.category());
289	        if (category != JudgmentCategory.RENDERING && category != JudgmentCategory.DESTRUCTION) {
290	            throw ApiException.unprocessable("无害化处理回执仅支持化制（RENDERING）与销毁（DESTRUCTION）类别");
291	        }
292	        String now = now();
293	        if (BatchStatus.RELEASED.name().equals(batch.status())) {
294	            repo.insertReceipt(batch.id(), req.receiptNo(), category.name(), req.headCount(),
295	                    req.processor(), true, now);
296	            repo.insertLateEvent(batch.id(), "LATE_RECEIPT",
297	                    "核销后迟到回执 " + req.receiptNo() + "，类别 " + category.name()
298	                            + "，头只数 " + req.headCount(),
299	                    now);
300	            log.warn("批次 {} 已出厂核销，回执 {} 迟到登记并告警", batchNo, req.receiptNo());
301	            return new ReceiptResponse(batchNo, req.receiptNo(), category.name(), req.headCount(),
302	                    true, reconciliation(batch.id()));
303	        }
304	        if (!BatchStatus.JUDGED.name().equals(batch.status())
305	                && !BatchStatus.SPECIAL_QUARANTINE.name().equals(batch.status())) {
306	            throw ApiException.conflict("批次未完成判定分流，不允许登记无害化处理回执");
307	        }
308	        repo.insertReceipt(batch.id(), req.receiptNo(), category.name(), req.headCount(),
309	                req.processor(), false, now);
310	        return new ReceiptResponse(batchNo, req.receiptNo(), category.name(), req.headCount(),
311	                false, reconciliation(batch.id()));
312	    }
313	
314	    // ---------- 出厂核销 ----------
315	
316	    /**
317	     * 出厂核销：回执头只数与判定数恰等受理、不等拒绝；核销为终态，重复核销返回幂等成功。
318	     */
319	    @Transactional
320	    public ReleaseResponse release(String batchNo, ReleaseRequest req) {
321	        return idempotent("release", req.requestId(), req, ReleaseResponse.class,
322	                () -> doRelease(batchNo));
323	    }
324	
325	    private ReleaseResponse doRelease(String batchNo) {
326	        BatchRow batch = mustFind(batchNo);
327	        // 先锁批次主行：与风险结果/变更同序互斥，杜绝阳性与出厂核销竞争放行。
328	        repo.lockBatch(batch.id());
329	        batch = mustFind(batchNo);
330	        if (BatchStatus.RELEASED.name().equals(batch.status())) {
331	            return new ReleaseResponse(batchNo, BatchStatus.RELEASED.name(), batch.releasedAt(),
332	                    reconciliation(batch.id()));
333	        }
334	        if (BatchStatus.SPECIAL_QUARANTINE.name().equals(batch.status())) {
335	            throw ApiException.conflict("批次处于专项隔离，四类判定保留但受控出厂拒绝");
336	        }
337	        if (!BatchStatus.JUDGED.name().equals(batch.status())) {
338	            throw ApiException.conflict("批次未达到可核销状态");
339	        }
340	        List<ReconciliationEntry> reconciliation = reconciliation(batch.id());
341	        List<String> mismatched = reconciliation.stream()
342	                .filter(e -> !e.matched())
343	                .map(e -> e.category() + "(判定 " + e.judgedCount() + " / 回执 " + e.receivedCount() + ")")
344	                .toList();
345	        if (!mismatched.isEmpty()) {
346	            throw ApiException.conflict("回执头只数与判定数不一致，拒绝出厂：" + mismatched);
347	        }
348	        // 风险抽检门禁：受控批次全部清单完成且全部样本阴性才解除；未受控批次直接通过。
349	        riskService.assertReleaseGate(batch.id());
350	        String now = now();
351	        int updated = repo.markReleased(batch.id(), now);
352	        if (updated == 0) {
353	            throw ApiException.conflict("并发核销冲突");
354	        }
355	        return new ReleaseResponse(batchNo, BatchStatus.RELEASED.name(), now, reconciliation);
356	    }
357	
358	    // ---------- 批次视图 ----------
359	
360	    /**
361	     * 批次全量视图：头只台账、判定明细与回执勾稽均可由明细复算。
362	     */
363	    @Transactional(readOnly = true)
364	    public BatchView getView(String batchNo) {
365	        BatchRow batch = mustFind(batchNo);
366	        List<BatchView.HeadView> heads = repo.findHeads(batch.id()).stream()
367	                .map(h -> new BatchView.HeadView(h.headNo(), h.status(), h.inspectionResult(),
368	                        h.judgmentCategory(), h.highTemp(), h.circulationArea(), h.inventoryMarked()))
369	                .toList();
370	        List<BatchView.JudgmentView> judgments = repo.findJudgments(batch.id()).stream()
371	                .map(j -> new BatchView.JudgmentView(j.headNo(), j.category(), j.highTemp(),
372	                        j.circulationArea()))
373	                .toList();
374	        List<BatchView.ReceiptView> receipts = repo.findReceipts(batch.id()).stream()
375	                .map(r -> new BatchView.ReceiptView(r.receiptNo(), r.category(), r.headCount(),
376	                        r.processor(), r.late(), r.receivedAt()))
377	                .toList();
378	        List<BatchView.LateEventView> lateEvents = repo.findLateEvents(batch.id()).stream()
379	                .map(e -> new BatchView.LateEventView(e.eventType(), e.detail(), e.createdAt()))
380	                .toList();
381	        return new BatchView(batch.batchNo(), batch.status(), batch.species(), batch.farmOrigin(),
382	                batch.declaredAt(), batch.preQuarantinedAt(), batch.judgedAt(), batch.releasedAt(),
383	                heads, judgments, receipts, lateEvents, reconciliation(batch.id()));
384	    }
385	
386	    // ---------- 内部：勾稽 / 幂等 / 工具 ----------
387	
388	    /** 回执勾稽：按化制/销毁类别对比判定头只数与已登记回执头只数（不含迟到回执），恰等一致。 */
389	    private List<ReconciliationEntry> reconciliation(long batchId) {
390	        List<JudgmentRow> judgments = repo.findJudgments(batchId);
391	        List<ReceiptRow> receipts = repo.findReceipts(batchId);
392	        List<ReconciliationEntry> entries = new ArrayList<>();
393	        for (JudgmentCategory category : List.of(JudgmentCategory.RENDERING, JudgmentCategory.DESTRUCTION)) {
394	            int judged = (int) judgments.stream()
395	                    .filter(j -> category.name().equals(j.category()))
396	                    .count();
397	            int received = receipts.stream()
398	                    .filter(r -> category.name().equals(r.category()) && !r.late())
399	                    .mapToInt(ReceiptRow::headCount)
400	                    .sum();
401	            entries.add(new ReconciliationEntry(category.name(), judged, received, judged == received));
402	        }
403	        return entries;
404	    }
405	
406	    /**
407	     * 幂等受理：指纹覆盖 requestId 与全部业务字段；同键同参返回首次结果，同键异参返回 409 且不改变批次状态。
408	     * 并发下同键请求依赖 requestId 全局唯一约束，仅首次受理成功，其余重放首次结果。
409	     */
410	    private <T> T idempotent(String endpoint, String requestId, Object request, Class<T> type,
411	                             Supplier<T> action) {
412	        String fingerprint = fingerprint(requestId, request);
413	        Optional<IdempotencyRow> existing = repo.findIdempotency(requestId);
414	        if (existing.isPresent()) {
415	            IdempotencyRow record = existing.get();
416	            if (!record.fingerprint().equals(fingerprint)) {
417	                throw ApiException.conflict("相同 requestId 携带不同业务参数，拒绝受理");
418	            }
419	            return readValue(record.responseBody(), type);
420	        }
421	        try {
422	            T result = action.get();
423	            repo.insertIdempotency(requestId, endpoint, fingerprint, writeValue(result), now());
424	            return result;
425	        } catch (DuplicateKeyException e) {
426	            Optional<IdempotencyRow> concurrent = repo.findIdempotency(requestId);
427	            if (concurrent.isPresent() && concurrent.get().fingerprint().equals(fingerprint)) {
428	                return readValue(concurrent.get().responseBody(), type);
429	            }
430	            throw ApiException.conflict("并发受理冲突：批次或请求标识已被其他请求占用");
431	        }
432	    }
433	
434	    private String fingerprint(String requestId, Object request) {
435	        try {
436	            String json = objectMapper.writeValueAsString(request);
437	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
438	            byte[] hash = digest.digest(
439	                    (requestId + "\n" + json).getBytes(StandardCharsets.UTF_8));
440	            StringBuilder hex = new StringBuilder(hash.length * 2);
441	            for (byte b : hash) {
442	                hex.append(Character.forDigit((b >> 4) & 0xF, 16));
443	                hex.append(Character.forDigit(b & 0xF, 16));
444	            }
445	            return hex.toString();
446	        } catch (Exception e) {
447	            throw new IllegalStateException("请求指纹计算失败", e);
448	        }
449	    }
450	
451	    private <T> T readValue(String json, Class<T> type) {
452	        try {
453	            return objectMapper.readValue(json, type);
454	        } catch (Exception e) {
455	            throw new IllegalStateException("幂等响应反序列化失败", e);
456	        }
457	    }
458	
459	    private String writeValue(Object value) {
460	        try {
461	            return objectMapper.writeValueAsString(value);
462	        } catch (Exception e) {
463	            throw new IllegalStateException("幂等响应序列化失败", e);
464	        }
465	    }
466	
467	    private BatchRow mustFind(String batchNo) {
468	        return repo.findBatchByNo(batchNo)
469	                .orElseThrow(() -> ApiException.notFound("批次不存在：" + batchNo));
470	    }
471	
472	    private JudgmentCategory parseCategory(String category) {
473	        try {
474	            return JudgmentCategory.valueOf(category);
475	        } catch (Exception e) {
476	            throw ApiException.unprocessable("未知判定类别：" + category
477	                    + "，支持 QUALIFIED/CONDITIONAL/RENDERING/DESTRUCTION");
478	        }
479	    }
480	
481	    private void validateDistinctHeadNos(List<String> headNos) {
482	        Set<String> seen = new HashSet<>();
483	        for (String headNo : headNos) {
484	            if (!seen.add(headNo)) {
485	                throw ApiException.unprocessable("头只编号重复：" + headNo);
486	            }
487	        }
488	    }
489	
490	    private void insertHeads(long batchId, List<String> headNos, String now) {
491	        for (String headNo : headNos) {
492	            repo.insertHead(batchId, headNo, "PENDING", now);
493	        }
494	    }
495	
496	    private String now() {
497	        return Instant.now(clock).toString();
498	    }
499	}
