    /** 无害化处理回执登记（幂等）：化制/销毁闭环凭证。 */
    @PostMapping("/{batchNo}/receipts")
    public ReceiptResponse registerReceipt(@PathVariable String batchNo,
                                           @Valid @RequestBody ReceiptRequest request) {
