19	        this.jdbc = jdbc;
20	    }
21	
22	    /** 风险绑定行，每批至多一行。 */
23	    public record RiskBindingRow(long id, long batchId, int version, String level, String ruleVersion,
24	                                 long currentSequenceNo, String createdAt, String updatedAt) {
25	    }
26	
27	    /** 抽检清单冻结行。frozenDeclared/frozenSamples 为字典序 JSON 数组文本。 */
28	    public record ChecklistRow(long id, long batchId, long sequenceNo, String kind, String level,
29	                               String ruleVersion, String status, String frozenDeclared,
30	                               String frozenSamples, String createdAt, String completedAt) {
31	    }
