39	    public record ChangeEventRow(long id, long batchId, String eventType, String fromLevel, String toLevel,
40	                                 String fromRuleVersion, String toRuleVersion, long sequenceNo,
41	                                 int fromVersion, int toVersion, String createdAt) {
42	    }
43	
44	    private static final RowMapper<RiskBindingRow> BINDING_MAPPER = (rs, n) -> new RiskBindingRow(
45	            rs.getLong("id"), rs.getLong("batch_id"), rs.getInt("version"), rs.getString("level"),
46	            rs.getString("rule_version"), rs.getLong("current_sequence_no"),
47	            rs.getString("created_at"), rs.getString("updated_at"));
48	
