50	            rs.getLong("id"), rs.getLong("batch_id"), rs.getLong("sequence_no"), rs.getString("kind"),
51	            rs.getString("level"), rs.getString("rule_version"), rs.getString("status"),
52	            rs.getString("frozen_declared"), rs.getString("frozen_samples"),
53	            rs.getString("created_at"), rs.getString("completed_at"));
54	
55	    private static final RowMapper<SampleRow> SAMPLE_MAPPER = (rs, n) -> new SampleRow(
56	            rs.getLong("id"), rs.getLong("batch_id"), rs.getLong("sequence_no"), rs.getString("head_no"),
57	            rs.getString("result"), rs.getString("submitted_at"));
58	
59	    private static final RowMapper<ChangeEventRow> EVENT_MAPPER = (rs, n) -> new ChangeEventRow(
60	            rs.getLong("id"), rs.getLong("batch_id"), rs.getString("event_type"),
61	            rs.getString("from_level"), rs.getString("to_level"),
62	            rs.getString("from_rule_version"), rs.getString("to_rule_version"), rs.getLong("sequence_no"),
63	            rs.getInt("from_version"), rs.getInt("to_version"), rs.getString("created_at"));
64	
65	    // ---------- 风险绑定 ----------
66	
67	    public void insertBinding(long batchId, int version, String level, String ruleVersion,
68	                              long currentSequenceNo, String now) {
69	        jdbc.update("INSERT INTO risk_binding(batch_id, version, level, rule_version,"
70	                        + " current_sequence_no, created_at, updated_at) VALUES (?,?,?,?,?,?,?)",
71	                batchId, version, level, ruleVersion, currentSequenceNo, now, now);
72	    }
