74	    public Optional<RiskBindingRow> findBinding(long batchId) {
75	        List<RiskBindingRow> rows = jdbc.query(
76	                "SELECT * FROM risk_binding WHERE batch_id = ?", BINDING_MAPPER, batchId);
77	        return rows.stream().findFirst();
78	    }
