80	    /** 行锁读取风险绑定（须在事务内调用），用于变更/结果与批次状态互斥。 */
81	    public Optional<RiskBindingRow> findBindingForUpdate(long batchId) {
82	        List<RiskBindingRow> rows = jdbc.query(
83	                "SELECT * FROM risk_binding WHERE batch_id = ? FOR UPDATE", BINDING_MAPPER, batchId);
84	        return rows.stream().findFirst();
85	    }
86	
87	    /** 乐观更新绑定：仅当前版本等于 expectedVersion 时生效，返回受影响行数。 */
88	    public int updateBinding(long batchId, int expectedVersion, int newVersion, String level,
89	                             String ruleVersion, long currentSequenceNo, String now) {
90	        return jdbc.update("UPDATE risk_binding SET version = ?, level = ?, rule_version = ?,"
91	                        + " current_sequence_no = ?, updated_at = ? WHERE batch_id = ? AND version = ?",
92	                newVersion, level, ruleVersion, currentSequenceNo, now, batchId, expectedVersion);
93	    }
94	
95	    // ---------- 批次行锁与专项隔离 ----------
96	
97	    /** 非终态→SPECIAL_QUARANTINE 条件流转，返回受影响行数（RELEASED 终态不被覆盖）。 */
98	    public int markSpecialQuarantine(long batchId) {
99	        return jdbc.update("UPDATE slaughter_batch SET status = 'SPECIAL_QUARANTINE' WHERE id = ?"
100	                        + " AND status IN ('PRE_QUARANTINED','INSPECTING','PAUSED','JUDGED')",
101	                batchId);
102	    }
103	
104	    // ---------- 抽检清单 ----------
105	
106	    public void insertChecklist(long batchId, long sequenceNo, String kind, String level,
107	                                String ruleVersion, String status, String frozenDeclared,
