109	        jdbc.update("INSERT INTO risk_checklist(batch_id, sequence_no, kind, level, rule_version,"
110	                        + " status, frozen_declared, frozen_samples, created_at) VALUES (?,?,?,?,?,?,?,?,?)",
111	                batchId, sequenceNo, kind, level, ruleVersion, status, frozenDeclared, frozenSamples, now);
112	    }
113	
114	    public List<ChecklistRow> findChecklists(long batchId) {
115	        return jdbc.query("SELECT * FROM risk_checklist WHERE batch_id = ? ORDER BY sequence_no",
116	                CHECKLIST_MAPPER, batchId);
117	    }
