119	    public Optional<ChecklistRow> findChecklist(long batchId, long sequenceNo) {
120	        List<ChecklistRow> rows = jdbc.query(
121	                "SELECT * FROM risk_checklist WHERE batch_id = ? AND sequence_no = ?",
122	                CHECKLIST_MAPPER, batchId, sequenceNo);
123	        return rows.stream().findFirst();
124	    }
125	
126	    /** OPEN→COMPLETED 条件流转，返回受影响行数。 */
127	    public int completeChecklist(long batchId, long sequenceNo, String completedAt) {
128	        return jdbc.update("UPDATE risk_checklist SET status = 'COMPLETED', completed_at = ?"
129	                        + " WHERE batch_id = ? AND sequence_no = ? AND status = 'OPEN'",
130	                completedAt, batchId, sequenceNo);
131	    }
132	
133	    /** 原子扩充：更新当前清单冻结抽检集合与风险规则，清单序号与既有结果保持不变。 */
134	    public int expandChecklist(long batchId, long sequenceNo, String level, String ruleVersion,
135	                               String frozenSamples, String now) {
136	        return jdbc.update("UPDATE risk_checklist SET kind = 'EXPANDED', level = ?, rule_version = ?,"
137	                        + " frozen_samples = ? WHERE batch_id = ? AND sequence_no = ? AND status = 'OPEN'",
138	                level, ruleVersion, frozenSamples, batchId, sequenceNo);
139	    }
140	
141	    // ---------- 逐只结果 ----------
142	
143	    public void insertSample(long batchId, long sequenceNo, String headNo, String result,
144	                             String submittedAt) {
145	        jdbc.update("INSERT INTO risk_sample(batch_id, sequence_no, head_no, result, submitted_at)"
146	                        + " VALUES (?,?,?,?,?)",
147	                batchId, sequenceNo, headNo, result, submittedAt);
148	    }
149	
150	    public List<SampleRow> findSamples(long batchId, long sequenceNo) {
151	        return jdbc.query("SELECT * FROM risk_sample WHERE batch_id = ? AND sequence_no = ?"
152	                        + " ORDER BY head_no",
153	                SAMPLE_MAPPER, batchId, sequenceNo);
154	    }
155	
156	    public List<SampleRow> findAllSamples(long batchId) {
157	        return jdbc.query("SELECT * FROM risk_sample WHERE batch_id = ? ORDER BY sequence_no, head_no",
158	                SAMPLE_MAPPER, batchId);
159	    }
160	
161	    // ---------- 变更证据 ----------
162	
163	    public void insertChangeEvent(long batchId, String eventType, String fromLevel, String toLevel,
164	                                  String fromRuleVersion, String toRuleVersion, long sequenceNo,
165	                                  int fromVersion, int toVersion, String now) {
166	        jdbc.update("INSERT INTO risk_change_event(batch_id, event_type, from_level, to_level,"
167	                        + " from_rule_version, to_rule_version, sequence_no, from_version, to_version,"
168	                        + " created_at) VALUES (?,?,?,?,?,?,?,?,?,?)",
169	                batchId, eventType, fromLevel, toLevel, fromRuleVersion, toRuleVersion, sequenceNo,
170	                fromVersion, toVersion, now);
171	    }
