29	class ConcurrencyTest extends BaseIntegrationTest {
30	
31	    @Autowired
32	    private BatchService service;
33	
34	    @Test
35	    @DisplayName("并发申报同一批次：唯一受理，其余冲突")
36	    void concurrentDeclareSameBatchOnlyOneAccepted() throws Exception {
37	        DeclareRequest a = new DeclareRequest("req-a", "B-CONC", "PIG", "合成养殖场", List.of("H1"));
38	        DeclareRequest b = new DeclareRequest("req-b", "B-CONC", "PIG", "合成养殖场", List.of("H1"));
39	
40	        List<Outcome<DeclareResponse>> outcomes = runConcurrently(
41	                () -> service.declare(a), () -> service.declare(b));
42	
43	        long successes = outcomes.stream().filter(o -> o.error() == null).count();
44	        long conflicts = outcomes.stream()
45	                .filter(o -> o.error() != null && o.error().status() == 409).count();
46	        assertEquals(1, successes, "并发申报须唯一受理");
47	        assertEquals(1, conflicts, "未受理方须返回 409 冲突");
48	        assertEquals(1, countRows("slaughter_batch"));
49	        assertEquals(1, countRows("head_ledger"));
50	    }
51	
52	    @Test
53	    @DisplayName("同键同参并发申报：均返回首次结果且只建档一次")
54	    void concurrentSameRequestIdReturnsFirstResult() throws Exception {
55	        DeclareRequest request = new DeclareRequest("req-same", "B-CONC2", "PIG", "合成养殖场",
56	                List.of("H1", "H2"));
57	
58	        List<Outcome<DeclareResponse>> outcomes = runConcurrently(
59	                () -> service.declare(request), () -> service.declare(request));
60	
61	        assertTrue(outcomes.stream().allMatch(o -> o.error() == null),
62	                "同键同参并发须均成功重放");
63	        DeclareResponse first = outcomes.get(0).value();
64	        DeclareResponse second = outcomes.get(1).value();
65	        assertEquals(first, second);
66	        assertEquals(1, countRows("slaughter_batch"));
67	        assertEquals(2, countRows("head_ledger"));
68	        assertEquals(1, countRows("idempotency_record"));
69	    }
