71	    @Test
72	    @DisplayName("同一批次同时刻只允许一条检验链：并发宰前检疫唯一放行")
73	    void concurrentPreQuarantineSingleChain() throws Exception {
74	        declareOk("d-1", "B-CHAIN", List.of("H1"));
75	
76	        List<Outcome<Object>> outcomes = runConcurrently(
77	                () -> service.preQuarantine("B-CHAIN", new PreQuarantineRequest("pq-a", "检疫员甲")),
78	                () -> service.preQuarantine("B-CHAIN", new PreQuarantineRequest("pq-b", "检疫员乙")));
79	
80	        long successes = outcomes.stream().filter(o -> o.error() == null).count();
81	        long conflicts = outcomes.stream()
82	                .filter(o -> o.error() != null && o.error().status() == 409).count();
83	        assertEquals(1, successes, "同一批次同时刻只允许一条检验链");
84	        assertEquals(1, conflicts);
85	        assertEquals("PRE_QUARANTINED", getView("B-CHAIN").status());
86	    }
