88	    // ---------- 并发辅助 ----------
89	
90	    /** 并发执行结果：成功值或业务异常。 */
91	    private record Outcome<T>(T value, ApiException error) {
92	    }
93	
94	    /**
95	     * 真实并发执行两个操作：统一栅栏同时起跑，15 秒超时，返回双方结果。
96	     */
97	    private <T> List<Outcome<T>> runConcurrently(Supplier<T> first, Supplier<T> second)
98	            throws Exception {
99	        ExecutorService pool = Executors.newFixedThreadPool(2);
100	        CountDownLatch ready = new CountDownLatch(2);
101	        CountDownLatch start = new CountDownLatch(1);
102	        try {
103	            Callable<Outcome<T>> taskFirst = () -> awaitAndRun(ready, start, first);
104	            Callable<Outcome<T>> taskSecond = () -> awaitAndRun(ready, start, second);
105	            Future<Outcome<T>> futureFirst = pool.submit(taskFirst);
106	            Future<Outcome<T>> futureSecond = pool.submit(taskSecond);
107	            assertTrue(ready.await(10, TimeUnit.SECONDS), "并发线程未就绪");
108	            start.countDown();
109	            Outcome<T> outcomeFirst = futureFirst.get(15, TimeUnit.SECONDS);
110	            Outcome<T> outcomeSecond = futureSecond.get(15, TimeUnit.SECONDS);
111	            assertNotNull(outcomeFirst);
112	            assertNotNull(outcomeSecond);
113	            return List.of(outcomeFirst, outcomeSecond);
114	        } finally {
115	            pool.shutdownNow();
116	            assertTrue(pool.awaitTermination(10, TimeUnit.SECONDS), "并发线程未在超时内结束");
117	        }
118	    }
119	
120	    private static <T> Outcome<T> awaitAndRun(CountDownLatch ready, CountDownLatch start,
121	                                              Supplier<T> action) throws Exception {
122	        ready.countDown();
123	        start.await(10, TimeUnit.SECONDS);
124	        try {
125	            return new Outcome<>(action.get(), null);
126	        } catch (ApiException e) {
127	            return new Outcome<>(null, e);
128	        }
129	    }
130	}
