     * @param circulationArea 有条件食用限定流通区域；类别为 CONDITIONAL 时必填
     */
    public record JudgmentItem(
            @NotBlank String headNo,
            @NotBlank String category,
            Boolean highTemp,
            String circulationArea) {
    }
}

