        postJson("/api/batches/B-ALL/shipments/vehicles",
                new VehicleCreateRequest("vc-2", "京A-2", List.of("H01", "H02", "H03"), 0,
                        clock.instant().toString()))
                .andExpect(status().isConflict());
        // 只有第一车的 H01 被占用
        Integer reservedHeads = jdbc.queryForObject(
