                .andExpect(status().isConflict());
    }

    @Test
    @DisplayName("车单创建同键同参重放原响应，异参409")
    void vehicleCreateIdempotentReplayAndConflict() throws Exception {
        readyAllQualified("B-IDEM", 3);
