31	/**
32	 * 分车出厂服务：启用分车、车单全量预占、未发车撤销、逐车核销与按头只进度查询。
33	 * 原逐头同步检验、风险抽检门禁与无害化回执门禁保留，逐车核销事务内重查全部门禁。
34	 */
35	@Service
36	public class ShipmentService {
37	
38	    private final BatchRepository batchRepo;
39	    private final ShipmentRepository shipmentRepo;
40	    private final RiskService riskService;
41	    /** 复用原无害化回执处置门禁勾稽，逐车核销事务内重查。 */
42	    private final BatchService batchService;
43	    private final Clock clock;
44	    private final ObjectMapper objectMapper;
45	    private final IdempotentExecutor idempotency;
46	
47	    public ShipmentService(BatchRepository batchRepo, ShipmentRepository shipmentRepo,
48	                           RiskService riskService, BatchService batchService, Clock clock,
49	                           ObjectMapper objectMapper, IdempotentExecutor idempotency) {
50	        this.batchRepo = batchRepo;
51	        this.shipmentRepo = shipmentRepo;
52	        this.riskService = riskService;
53	        this.batchService = batchService;
54	        this.clock = clock;
55	        this.objectMapper = objectMapper;
56	        this.idempotency = idempotency;
57	    }
58	
59	    /** 启用分车出厂（幂等）：有合格头只且尚未出厂的批次可启用。 */
60	    @Transactional
61	    public SplitEnableResponse enableSplit(String batchNo, SplitEnableRequest req) {
62	        parseOccurredAt(req.occurredAt());
63	        return idempotency.run("split-enable", req.requestId(), req, SplitEnableResponse.class,
64	                () -> doEnableSplit(batchNo));
65	    }
66	
67	    private SplitEnableResponse doEnableSplit(String batchNo) {
68	        BatchRow batch = lockAndReload(batchNo);
69	        int qualified = batchRepo.countQualifiedHeads(batch.id());
70	        // 已启用：幂等返回当前状态（不要求仍有未出厂头只，终态后查询同样稳定）。
71	        if (batch.splitEnabled()) {
72	            return new SplitEnableResponse(batchNo, batch.status(), true, qualified);
73	        }
74	        if (BatchStatus.RELEASED.name().equals(batch.status())) {
75	            throw ApiException.conflict("批次已最终出厂，不允许再启用分车");
76	        }
77	        if (qualified <= 0) {
78	            throw ApiException.conflict("批次尚无合格头只，不允许启用分车出厂");
79	        }
80	        int updated = batchRepo.enableSplit(batch.id());
81	        if (updated == 0) {
82	            throw ApiException.conflict("并发冲突：分车启用状态已变化");
83	        }
84	        batch = mustFindBatch(batchNo);
85	        return new SplitEnableResponse(batchNo, batch.status(), true, qualified);
86	    }
87	
88	    /** 创建车辆清单并全量预占（幂等）：缺一项全单不占，创建后冻结。 */
89	    @Transactional
90	    public VehicleView createVehicle(String batchNo, VehicleCreateRequest req) {
91	        parseOccurredAt(req.occurredAt());
92	        return idempotency.run("vehicle-create", req.requestId(), req, VehicleView.class,
93	                () -> doCreateVehicle(batchNo, req));
94	    }
95	
96	    private VehicleView doCreateVehicle(String batchNo, VehicleCreateRequest req) {
97	        BatchRow batch = lockAndReload(batchNo);
98	        if (!batch.splitEnabled()) {
99	            throw ApiException.conflict("批次尚未启用分车出厂，不允许建立车辆清单");
100	        }
101	        if (BatchStatus.RELEASED.name().equals(batch.status())) {
102	            throw ApiException.conflict("批次已最终出厂，不允许再建立车辆清单");
103	        }
104	        if (req.expectedVersion() != 0) {
105	            throw ApiException.conflict("新建车辆清单 expectedVersion 须为 0，成功后车单版本为 1");
106	        }
107	        if (shipmentRepo.findVehicleByNo(batch.id(), req.vehicleNo()).isPresent()) {
108	            throw ApiException.conflict("合成车号已存在：" + req.vehicleNo() + "，车单创建后不可改单");
109	        }
110	        List<String> frozen = normalizeHeads(req.headNos());
111	        if (frozen.size() > 50) {
112	            throw ApiException.badRequest("每车头只数须在 1 至 50 个之间");
113	        }
114	        // 出厂合格头只集合取原判定明细：跨批/病害处置头只一律拒绝。
115	        Set<String> qualified = new HashSet<>(batchRepo.findQualifiedHeadNos(batch.id()));
116	        List<String> notQualified = frozen.stream().filter(h -> !qualified.contains(h)).toList();
117	        if (!notQualified.isEmpty()) {
118	            throw ApiException.unprocessable("头只不属于本批合格集合（含跨批或病害处置头只），拒绝建单："
119	                    + notQualified);
120	        }
121	        // 批次行锁已在建单事务间串行；再显式核对占用，给出明确冲突信息。
122	        Set<String> occupied = new HashSet<>();
123	        for (ShipmentHeadRow row : shipmentRepo.findShipmentHeads(batch.id())) {
124	            occupied.add(row.headNo());
125	        }
126	        List<String> alreadyOccupied = frozen.stream().filter(occupied::contains).toList();
127	        if (!alreadyOccupied.isEmpty()) {
128	            throw ApiException.conflict("头只已被其他未撤销车辆占用，同头只争车只一方成功："
129	                    + alreadyOccupied);
130	        }
131	        String now = now();
132	        long vehicleId;
133	        try {
134	            vehicleId = shipmentRepo.insertVehicle(batch.id(), req.vehicleNo(), frozen.size(),
135	                    toJson(frozen), now);
136	            for (String headNo : frozen) {
137	                shipmentRepo.insertShipmentHead(batch.id(), vehicleId, headNo, now);
138	            }
139	        } catch (DuplicateKeyException e) {
140	            // 唯一约束兜底（车号冲突或头只争车）：整单回滚，缺一项全单不占。
141	            throw ApiException.conflict("车辆清单预占冲突：车号重复或头只已被其他未撤销车辆占用");
142	        }
143	        VehicleRow vehicle = shipmentRepo.findVehicleByNo(batch.id(), req.vehicleNo()).orElseThrow();
144	        return toView(batchNo, vehicle, batch.status());
145	    }
146	
147	    /** 撤销未发车清单并释放全部预占（幂等），不能事后改单。 */
148	    @Transactional
149	    public VehicleView revokeVehicle(String batchNo, String vehicleNo, VehicleRevokeRequest req) {
150	        parseOccurredAt(req.occurredAt());
151	        return idempotency.run("vehicle-revoke", req.requestId(), req, VehicleView.class,
152	                () -> doRevokeVehicle(batchNo, vehicleNo, req));
153	    }
154	
155	    private VehicleView doRevokeVehicle(String batchNo, String vehicleNo, VehicleRevokeRequest req) {
156	        BatchRow batch = lockAndReload(batchNo);
157	        VehicleRow vehicle = shipmentRepo.findVehicleByNoForUpdate(batch.id(), vehicleNo)
158	                .orElseThrow(() -> ApiException.notFound("车辆清单不存在：" + vehicleNo));
159	        if (VehicleStatus.DEPARTED.name().equals(vehicle.status())) {
160	            throw ApiException.conflict("车辆已发车出厂，车单冻结不可撤销：" + vehicleNo);
161	        }
162	        if (VehicleStatus.REVOKED.name().equals(vehicle.status())) {
163	            throw ApiException.conflict("车辆清单已撤销，终态不可重复撤销：" + vehicleNo);
164	        }
165	        if (req.expectedVersion() != vehicle.version()) {
166	            throw ApiException.conflict("车单版本不匹配：expectedVersion=" + req.expectedVersion()
167	                    + "，当前版本=" + vehicle.version());
168	        }
169	        String now = now();
170	        int updated = shipmentRepo.transitionVehicle(vehicle.id(),
171	                VehicleStatus.RESERVED.name(), vehicle.version(),
172	                VehicleStatus.REVOKED.name(), vehicle.version() + 1, "revoked_at", now);
173	        if (updated == 0) {
174	            throw ApiException.conflict("并发冲突：车辆清单状态或版本已变化，撤销失败");
175	        }
176	        // 释放全部预占：删除预占行后这些头只可被其他车重新预占。
177	        shipmentRepo.deleteShipmentHeads(batch.id(), vehicle.id());
178	        VehicleRow revoked = shipmentRepo.findVehicleByNo(batch.id(), vehicleNo).orElseThrow();
179	        return toView(batchNo, revoked, batch.status());
180	    }
181	
182	    /** 逐车核销（幂等）：事务内重查抽检/处置门禁、车单与版本，全部满足才整车转已出厂。 */
183	    @Transactional
184	    public VehicleView departVehicle(String batchNo, String vehicleNo, VehicleDepartRequest req) {
185	        parseOccurredAt(req.occurredAt());
186	        return idempotency.run("vehicle-depart", req.requestId(), req, VehicleView.class,
187	                () -> doDepartVehicle(batchNo, vehicleNo, req));
188	    }
189	
190	    private VehicleView doDepartVehicle(String batchNo, String vehicleNo, VehicleDepartRequest req) {
191	        BatchRow batch = lockAndReload(batchNo);
192	        if (!batch.splitEnabled()) {
193	            throw ApiException.conflict("批次未启用分车，不能走逐车核销入口");
194	        }
195	        if (BatchStatus.RELEASED.name().equals(batch.status())) {
196	            throw ApiException.conflict("批次已最终出厂，全部合格头只已核销完");
197	        }
198	        if (BatchStatus.SPECIAL_QUARANTINE.name().equals(batch.status())) {
199	            throw ApiException.conflict("批次处于专项隔离，受控逐车出厂拒绝");
200	        }
201	        VehicleRow vehicle = shipmentRepo.findVehicleByNoForUpdate(batch.id(), vehicleNo)
202	                .orElseThrow(() -> ApiException.notFound("车辆清单不存在：" + vehicleNo));
203	        if (VehicleStatus.REVOKED.name().equals(vehicle.status())) {
204	            throw ApiException.conflict("车辆清单已撤销释放，不能发车：" + vehicleNo);
205	        }
206	        if (VehicleStatus.DEPARTED.name().equals(vehicle.status())) {
207	            throw ApiException.conflict("车辆已发车出厂，车单冻结不可重复核销：" + vehicleNo);
208	        }
209	        if (req.expectedVersion() != vehicle.version()) {
210	            throw ApiException.conflict("车单版本不匹配：expectedVersion=" + req.expectedVersion()
211	                    + "，当前版本=" + vehicle.version());
212	        }
213	        // 事务内重查原全批门禁：无害化回执勾稽 + 风险抽检（受控批全部清单完成且全阴）。
214	        batchService.assertReceiptReconciled(batch.id());
215	        riskService.assertReleaseGate(batch.id());
216	
217	        String now = now();
218	        // 单车不得部分核销：本车全部 RESERVED 头只一次性转已出厂，受影响行数须恰等于冻结数。
219	        int marked = shipmentRepo.markHeadsDeparted(batch.id(), vehicle.id(), now);
220	        if (marked != vehicle.headCount()) {
221	            throw ApiException.conflict("车辆预占头只数与清单不一致（" + marked + "/"
222	                    + vehicle.headCount() + "），禁止部分核销，保留原预占");
223	        }
224	        int updated = shipmentRepo.transitionVehicle(vehicle.id(),
225	                VehicleStatus.RESERVED.name(), vehicle.version(),
226	                VehicleStatus.DEPARTED.name(), vehicle.version() + 1, "departed_at", now);
227	        if (updated == 0) {
228	            throw ApiException.conflict("并发冲突：车辆清单状态或版本已变化，核销失败保留原预占");
229	        }
230	
231	        // 末车收口：全部合格头只恰核销完（按头只勾稽，不把病害头只算进未出厂）才转最终出厂。
232	        int qualifiedTotal = batchRepo.countQualifiedHeads(batch.id());
233	        long departedTotal = shipmentRepo.findShipmentHeads(batch.id()).stream()
234	                .filter(h -> "DEPARTED".equals(h.status()))
235	                .count();
236	        String finalBatchStatus = batch.status();
237	        if (departedTotal == qualifiedTotal) {
238	            int released = batchRepo.markReleased(batch.id(), now);
239	            if (released == 0) {
240	                throw ApiException.conflict("并发冲突：批次终态流转失败，本次车单核销与批次收口保持同事务");
241	            }
242	            finalBatchStatus = BatchStatus.RELEASED.name();
243	        } else if (departedTotal > qualifiedTotal) {
244	            throw ApiException.conflict("已出厂合格头只数超过合格判定数，勾稽异常："
245	                    + departedTotal + "/" + qualifiedTotal);
246	        }
247	        VehicleRow departed = shipmentRepo.findVehicleByNo(batch.id(), vehicleNo).orElseThrow();
248	        return toView(batchNo, departed, finalBatchStatus);
249	    }
250	
251	    /** 分车进度查询：每车冻结清单、已出厂/未出厂头只及批次进度，按头只勾稽。 */
252	    @Transactional(readOnly = true)
253	    public ShipmentProgressView getProgress(String batchNo) {
254	        BatchRow batch = mustFindBatch(batchNo);
255	        List<String> qualified = batchRepo.findQualifiedHeadNos(batch.id());
256	        List<VehicleRow> vehicleRows = shipmentRepo.findVehicles(batch.id());
257	        List<ShipmentHeadRow> headRows = shipmentRepo.findShipmentHeads(batch.id());
258	
259	        List<String> departed = new ArrayList<>();
260	        List<String> reserved = new ArrayList<>();
261	        for (ShipmentHeadRow row : headRows) {
262	            if ("DEPARTED".equals(row.status())) {
263	                departed.add(row.headNo());
264	            } else if ("RESERVED".equals(row.status())) {
265	                reserved.add(row.headNo());
266	            }
267	        }
268	        departed.sort(String::compareTo);
269	        reserved.sort(String::compareTo);
270	        // 未出厂 = 合格全集 − 已出厂；病害处置头只本就不在合格全集，故不会被算进未出厂人数。
271	        Set<String> departedSet = new HashSet<>(departed);
272	        List<String> unshipped = qualified.stream()
273	                .filter(h -> !departedSet.contains(h))
274	                .toList();
275	
276	        List<VehicleView> vehicles = vehicleRows.stream()
277	                .map(v -> toView(batchNo, v, batch.status()))
278	                .toList();
279	        boolean allShipped = !qualified.isEmpty() && departed.size() == qualified.size();
280	        return new ShipmentProgressView(batchNo, batch.status(), batch.splitEnabled(),
281	                qualified.size(), List.copyOf(departed), List.copyOf(reserved),
282	                List.copyOf(unshipped), departed.size(), unshipped.size(), allShipped, vehicles);
283	    }
284	
285	    // ---------- 内部：加锁与工具 ----------
286	
287	    /** 锁定批次主行并重读最新状态，与风险变更/结果及整批出厂核销同序互斥。 */
288	    private BatchRow lockAndReload(String batchNo) {
289	        BatchRow batch = mustFindBatch(batchNo);
290	        batchRepo.lockBatch(batch.id());
291	        return batchRepo.findBatchByNo(batchNo).orElseThrow();
292	    }
293	
294	    private BatchRow mustFindBatch(String batchNo) {
295	        return batchRepo.findBatchByNo(batchNo)
296	                .orElseThrow(() -> ApiException.notFound("批次不存在：" + batchNo));
297	    }
298	
299	    private String parseOccurredAt(String occurredAt) {
300	        try {
301	            return Instant.parse(occurredAt).toString();
302	        } catch (Exception e) {
303	            throw ApiException.badRequest("occurredAt 须为 UTC ISO-8601 时刻：" + occurredAt);
304	        }
305	    }
306	
307	    /** 头只标识去重并按字典序排序；重复标识视为非法（车单须给出不同头只）。 */
308	    private List<String> normalizeHeads(List<String> headNos) {
309	        Set<String> distinct = new LinkedHashSet<>();
310	        for (String headNo : headNos) {
311	            if (!distinct.add(headNo)) {
312	                throw ApiException.badRequest("车辆清单头只标识重复：" + headNo);
313	            }
314	        }
315	        List<String> sorted = new ArrayList<>(distinct);
316	        sorted.sort(String::compareTo);
317	        return List.copyOf(sorted);
318	    }
319	
320	    /** 由车单行组装冻结视图，批次终态与批次状态由调用方按操作后状态传入。 */
321	    private VehicleView toView(String batchNo, VehicleRow vehicle, String batchStatus) {
322	        boolean released = BatchStatus.RELEASED.name().equals(batchStatus);
323	        return new VehicleView(batchNo, vehicle.vehicleNo(), vehicle.version(), vehicle.status(),
324	                fromJson(vehicle.frozenHeads()), vehicle.headCount(), vehicle.createdAt(),
325	                vehicle.departedAt(), vehicle.revokedAt(), batchStatus, released);
326	    }
327	
328	    private String toJson(List<String> values) {
329	        try {
330	            return objectMapper.writeValueAsString(values);
331	        } catch (Exception e) {
332	            throw new IllegalStateException("冻结清单序列化失败", e);
333	        }
334	    }
335	
336	    private List<String> fromJson(String json) {
337	        try {
338	            return objectMapper.readValue(json,
339	                    objectMapper.getTypeFactory().constructCollectionType(List.class, String.class));
340	        } catch (Exception e) {
341	            throw new IllegalStateException("冻结清单反序列化失败", e);
342	        }
343	    }
344	
345	    private String now() {
346	        return Instant.now(clock).toString();
347	    }
348	}
